item.aggregated_output:
  1	import {createHash} from "node:crypto";
  2	
  3	import {aggregateDebtViews, calculateCovenantHeadroom, calculateImpliedEbitda, calculateLeverage} from "@offroad/financial-core";
  4	import Decimal from "decimal.js";
  5	import {z} from "zod";
  6	
  7	/**
  8	 * Executor of the method `reconcile-covenant-definitions` (v12, after the eleventh independent review).
  9	 * It never writes "breached". Each indenture carries the anchor of its definitions and one anchor per
 10	 * tier; EBITDA adjustments are typed (denominator additions versus numerator obligations) and never
 11	 * folded together; the net debt of each instrument is computed from that instrument's own component
 12	 * list over dated component values with their own anchors, so a definition that adds leases or drops
 13	 * derivatives changes the number or refuses the comparison; the reported index is comparable only at
 14	 * the as-of date, with the same components and an opened EBITDA value; an ordinary settlement needs
 15	 * its date (so does an accelerated one); the next measurement follows the frequency the indenture
 16	 * states; every unproven tier leaves a written condition; a numerator obligation (sellers finance) is
 17	 * modeled with its own value or left as a legal condition, never folded into the EBITDA declaration;
 18	 * a legal condition on the numerator caps comparability; component lines, EBITDA and opening carry a
 19	 * unit and a twelve-month period. Net debt, leverage and headroom run through financial-core.
 20	 */
 21	const ratio = z.string().regex(/^\d+(\.\d+)?$/);
 22	const money = z.string().regex(/^-?\d+(\.\d+)?$/);
 23	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
 24	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
 25	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
 26	/** An indenture anchor cites a numbered clause (4.22.3(j), 7.24.3(VIII)); a label such as "índice financeiro" is not a clause. */
 27	const indentureAnchorSchema = z.object({document: z.string().min(1), clause: z.string().regex(/\d+(\.\d+)+/, "an indenture anchor needs a numbered clause"), page: z.number().int().positive()}).strict();
 28	const anchorSchema = z.object({document: z.string().min(1), clause: z.string().optional(), page: z.number().int().positive().optional(), note: z.string().optional()}).strict();
 29	type Anchor = z.infer<typeof anchorSchema>;
 30	
 31	/** The components a net debt definition is built from; comparability is decided on these, not on prose. */
 32	export const netDebtComponentSchema = z.enum([
 33	  "loans_and_financings", "debentures", "derivative_liabilities", "other_onerous_debt", "leases",
 34	  "cash_and_equivalents", "financial_investments", "derivative_assets",
 35	]);
 36	type NetDebtComponent = z.infer<typeof netDebtComponentSchema>;
 37	const DEDUCTIONS = new Set<NetDebtComponent>(["cash_and_equivalents", "financial_investments", "derivative_assets"]);
 38	/** The words a clause uses for each component; a structured component the text never names is a tag, not a definition. */
 39	const COMPONENT_WORDS: Record<NetDebtComponent, RegExp> = {
 40	  loans_and_financings: /emprestim|financiament|loan|borrowing|divida bruta|gross debt/,
 41	  debentures: /debenture|divida bruta|gross debt/,
 42	  derivative_liabilities: /derivativ|derivative/,
 43	  other_onerous_debt: /outra|other|onerosa|onerous/,
 44	  leases: /arrendament|lease/,
 45	  cash_and_equivalents: /caixa|disponibilidade|cash/,
 46	  financial_investments: /aplicac|investment/,
 47	  derivative_assets: /derivativ|derivative/,
 48	};
 49	/** An open-ended residual ("qualquer outra dívida onerosa"): its absence from the base is a condition, not a mismatch. */
 50	const RESIDUAL: NetDebtComponent = "other_onerous_debt";
 51	
 52	
 53	export const covenantTierSchema = z.object({
 54	  limit: ratio,
 55	  condition: z.discriminatedUnion("type", [
 56	    z.object({type: z.literal("unconditional")}).strict(),
 57	    z.object({type: z.literal("until_reference_settled"), referenceInstruments: z.array(z.string().min(1)).min(1)}).strict(),
 58	    z.object({type: z.literal("after_reference_settled"), referenceInstruments: z.array(z.string().min(1)).min(1)}).strict(),
 59	  ]),
 60	  anchor: indentureAnchorSchema,
 61	}).strict();
 62	
 63	/** Adjustments beyond the base EBITDA definition, typed by the side of the ratio they touch. */
 64	export const ebitdaAdjustmentSchema = z.object({
 65	  id: z.string().min(1),
 66	  kind: z.enum(["denominator_addition", "numerator_obligation", "other"]),
 67	  description: z.string().min(1),
 68	  anchor: indentureAnchorSchema,
 69	  /** For a numerator obligation: its dated value in the base, or null when the base does not state it. */
 70	  obligation: z.object({value: nonNegative, asOf: isoDate, anchor: anchorSchema}).strict().nullable().default(null),
 71	}).strict();
 72	
 73	export const covenantInstrumentSchema = z.discriminatedUnion("source", [
 74	  z.object({
 75	    source: z.literal("indenture"),
 76	    id: z.string().min(1),
 77	    indexName: z.string().min(1),
 78	    direction: z.enum(["maximum", "minimum"]).default("maximum"),
 79	    netDebtDefinition: z.string().min(1),
 80	    /** The perimeter the definition measures; the reported index must match it to be comparable. */
 81	    perimeter: z.enum(["consolidated", "parent"]).default("consolidated"),
 82	    netDebtComponents: z.array(netDebtComponentSchema).min(1),
 83	    ebitdaDefinition: z.string().min(1),
 84	    ebitdaAdjustments: z.array(ebitdaAdjustmentSchema).default([]),
 85	    measurement: z.object({frequency: z.enum(["annual", "semiannual", "quarterly"]), basis: z.string().min(1), fiscalYearEnd: z.string().regex(/^\d{2}-\d{2}$/)}).strict(),
 86	    /** Tiers in the order the indenture states them. */
 87	    tiers: z.array(covenantTierSchema).min(1),
 88	    /** One anchor per definition: the net debt clause and the EBITDA clause sit on different pages. */
 89	    definitionAnchors: z.object({netDebt: indentureAnchorSchema, ebitda: indentureAnchorSchema}).strict(),
 90	  }).strict(),
 91	  z.object({
 92	    source: z.literal("trustee_report"),
 93	    id: z.string().min(1),
 94	    indexName: z.string().min(1),
 95	    reportedLimit: ratio,
 96	    reportedMeasurement: z.object({value: ratio, asOf: isoDate}).strict().nullable().default(null),
 97	    anchor: anchorSchema,
 98	  }).strict(),
 99	]);
100	
101	/** One line of the base with the components it covers (an aggregated note line may cover two), its date and its own anchor. */
102	export const componentValueSchema = z.object({
103	  component: netDebtComponentSchema,
104	  covers: z.array(netDebtComponentSchema).min(1),
105	  value: nonNegative,
106	  unit: unitSchema,
107	  perimeter: z.enum(["consolidated", "parent"]).default("consolidated"),
108	  asOf: isoDate,
109	  anchor: anchorSchema,
110	}).strict();
111	
112	export const covenantReconciliationInputSchema = z.object({
113	  asOfDate: isoDate,
114	  /** The unit of every monetary value in the base; lines, EBITDA and openings must state the same. */
115	  unit: unitSchema,
116	  /** Where the source states the unit; its note must name that unit, so a relabelled scale is refused. */
117	  unitAnchor: anchorSchema.extend({note: z.string().min(1)}),
118	  instruments: z.array(covenantInstrumentSchema),
119	  referenceSettlements: z.array(z.object({
120	    instrument: z.string().min(1),
121	    maturityDate: isoDate,
122	    /** ordinary: settled in the ordinary course (needs the date); accelerated: settled by acceleration; outstanding: still alive; unknown: the base does not say. */
123	    settlement: z.enum(["ordinary", "accelerated", "outstanding", "unknown"]),
124	    settlementDate: isoDate.nullable().default(null),
125	    anchor: anchorSchema,
126	  }).strict()).default([]),
127	  componentValues: z.array(componentValueSchema).default([]),
128	  /** Dated lines of the base that may belong to a numerator obligation (acquisition payables, contingent consideration) but are not yet classified; they are carried as uncovered terms, never added and never called absent. */
129	  candidateObligations: z.array(z.object({id: z.string().min(1), description: z.string().min(1), value: nonNegative, unit: unitSchema, asOf: isoDate, relatedAdjustmentId: z.string().min(1).nullable().default(null), anchor: anchorSchema}).strict()).default([]),
130	  /** LTM EBITDA as the company computes it for the covenant, when it is opened, with the adjustment ids it already incorporates. */
131	  ltmEbitda: z.object({value: money, unit: unitSchema, perimeter: z.enum(["consolidated", "parent"]).default("consolidated"), asOf: isoDate, months: z.literal(12), incorporatesAdjustments: z.array(z.string().min(1)).default([]), anchor: anchorSchema}).strict().nullable().default(null),
132	  reported: z.object({
133	    value: ratio,
134	    asOf: isoDate,
135	    definition: z.string().min(1),
136	    /** The components the base actually enumerates for the reported net debt, not the contractual phrase. */
137	    netDebtComponents: z.array(netDebtComponentSchema).min(1),
138	    perimeter: z.enum(["consolidated", "parent"]).default("consolidated"),
139	    /** The opened EBITDA behind the reported index, when the base shows it; a flag is not an opening. */
140	    ebitdaOpening: z.object({value: money, unit: unitSchema, asOf: isoDate, months: z.literal(12), anchor: anchorSchema}).strict().nullable().default(null),
141	    anchor: anchorSchema,
142	  }).strict().nullable().default(null),
143	}).strict().superRefine((input, context) => {
144	  const UNIT_WORDS: Record<string, RegExp> = {"BRL": /\b(R\$|reais|BRL)\b(?!\s*(mil|milh))/i, "BRL thousand": /\b(mil|milhares|thousand)\b/i, "BRL million": /\b(milh[õo]es|million)\b/i, "USD": /\bUSD\b(?!\s*(mil|thousand))/i, "USD thousand": /\bUSD\b.*\b(mil|thousand)\b/i};
145	  if (!UNIT_WORDS[input.unit]!.test(input.unitAnchor.note)) context.addIssue({code: "custom", path: ["unitAnchor"], message: `the unit anchor's note does not name the unit ${input.unit}; a relabelled scale is refused`});
146	  const seenFacts = new Set<string>();
147	  input.referenceSettlements.forEach((fact, index) => {
148	    if (seenFacts.has(fact.instrument)) context.addIssue({code: "custom", path: ["referenceSettlements", index], message: `duplicate settlement fact for ${fact.instrument}`});
149	    seenFacts.add(fact.instrument);
150	    if ((fact.settlement === "ordinary" || fact.settlement === "accelerated") && fact.settlementDate === null) context.addIssue({code: "custom", path: ["referenceSettlements", index, "settlementDate"], message: `a settlement of ${fact.instrument} (${fact.settlement}) needs its date; without it the fact is unknown`});
151	  });
152	  const seenInstruments = new Set<string>();
153	  input.instruments.forEach((instrument, index) => {
154	    if (seenInstruments.has(instrument.id)) context.addIssue({code: "custom", path: ["instruments", index], message: `duplicate instrument ${instrument.id}`});
155	    seenInstruments.add(instrument.id);
156	    if (instrument.source === "indenture") {
157	      const text = instrument.netDebtDefinition.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
158	      for (const component of instrument.netDebtComponents) {
159	        if (!COMPONENT_WORDS[component].test(text)) context.addIssue({code: "custom", path: ["instruments", index, "netDebtComponents"], message: `${instrument.id}: the definition text never names the component ${component}; the structured components must be readable in the clause`});
160	      }
161	      // The other direction for the indenture too: a component the clause names must be in the structured list, with derivatives on the side the clause gives them.
162	      {
163	        const listed = new Set<string>(instrument.netDebtComponents);
164	        for (const [component, words] of Object.entries(COMPONENT_WORDS)) {
165	          if (component === "derivative_liabilities" || component === "derivative_assets" || component === "other_onerous_debt") continue;
166	          if (words.test(text) && !listed.has(component)) context.addIssue({code: "custom", path: ["instruments", index, "netDebtComponents"], message: `${instrument.id}: the definition text names ${component} and the structured components omit it; the clause and the list disagree`});
167	        }
168	        if (/derivativ/.test(text)) {
169	          const liabilities = /derivativ[^.;]{0,40}passiv|passiv[^.;]{0,40}derivativ|derivative liabilit/.test(text);
170	          const assets = /derivativ[^.;]{0,40}ativ(?!o? ?e)|ativ[^.;]{0,40}derivativ|derivative asset/.test(text);
171	          if (liabilities && !listed.has("derivative_liabilities")) context.addIssue({code: "custom", path: ["instruments", index, "netDebtComponents"], message: `${instrument.id}: the clause adds derivative liabilities and the structured components omit them`});
172	          if (assets && !listed.has("derivative_assets")) context.addIssue({code: "custom", path: ["instruments", index, "netDebtComponents"], message: `${instrument.id}: the clause deducts derivative assets and the structured components omit them`});
173	        }
174	      }
175	      const adjustmentIds = new Set<string>();
176	      instrument.ebitdaAdjustments.forEach((adjustment, position) => {
177	        if (adjustmentIds.has(adjustment.id)) context.addIssue({code: "custom", path: ["instruments", index, "ebitdaAdjustments", position], message: `duplicate adjustment ${adjustment.id}`});
178	        adjustmentIds.add(adjustment.id);
179	      });
180	    }
181	  });
182	  const covered = new Set<string>();
183	  input.componentValues.forEach((line, index) => {
184	    if (!line.covers.includes(line.component)) context.addIssue({code: "custom", path: ["componentValues", index, "covers"], message: "a line must cover its own component"});
185	    const sides = new Set(line.covers.map((component) => (DEDUCTIONS.has(component) ? "deduction" : "debt")));
186	    if (sides.size > 1) context.addIssue({code: "custom", path: ["componentValues", index, "covers"], message: `line ${line.component} aggregates debt and deductions; the base must decompose it before it enters a net debt`});
187	    if (line.asOf !== input.asOfDate) context.addIssue({code: "custom", path: ["componentValues", index, "asOf"], message: `component ${line.component} is dated ${line.asOf}, not the as-of date ${input.asOfDate}`});
188	    for (const component of line.covers) {
189	      if (covered.has(component)) context.addIssue({code: "custom", path: ["componentValues", index], message: `component ${component} is covered twice`});
190	      covered.add(component);
191	    }
192	  });
193	  if (input.ltmEbitda && input.ltmEbitda.asOf !== input.asOfDate) context.addIssue({code: "custom", path: ["ltmEbitda", "asOf"], message: "the opened EBITDA must be dated at the as-of date"});
194	  input.candidateObligations.forEach((candidate, index) => {
195	    if (candidate.unit !== input.unit) context.addIssue({code: "custom", path: ["candidateObligations", index, "unit"], message: `candidate ${candidate.id} is stated in ${candidate.unit}, not the base unit ${input.unit}`});
196	    if (candidate.asOf !== input.asOfDate) context.addIssue({code: "custom", path: ["candidateObligations", index, "asOf"], message: `candidate ${candidate.id} is dated ${candidate.asOf}, not the as-of date ${input.asOfDate}`});
197	  });
198	  if (input.reported?.ebitdaOpening && input.reported.ebitdaOpening.asOf !== input.asOfDate) context.addIssue({code: "custom", path: ["reported", "ebitdaOpening", "asOf"], message: "the EBITDA opening behind the reported index must be dated at the as-of date"});
199	  const units = new Set<string>([input.unit, ...input.componentValues.map((line) => line.unit), ...(input.ltmEbitda ? [input.ltmEbitda.unit] : []), ...(input.reported?.ebitdaOpening ? [input.reported.ebitdaOpening.unit] : [])]);
200	  if (units.size > 1) context.addIssue({code: "custom", path: ["componentValues"], message: `one unit per base: ${[...units].sort().join(", ")} were given`});

201	  input.instruments.forEach((instrument, index) => {
202	    if (instrument.source !== "indenture") return;
203	    instrument.ebitdaAdjustments.forEach((adjustment, position) => {
204	      if (adjustment.obligation && adjustment.kind !== "numerator_obligation") context.addIssue({code: "custom", path: ["instruments", index, "ebitdaAdjustments", position, "obligation"], message: "only a numerator obligation carries an obligation value"});
205	      if (adjustment.obligation && adjustment.obligation.asOf !== input.asOfDate) context.addIssue({code: "custom", path: ["instruments", index, "ebitdaAdjustments", position, "obligation", "asOf"], message: "an obligation value must be dated at the as-of date"});
206	    });
207	  });
208	  if (input.reported && input.reported.asOf > input.asOfDate) context.addIssue({code: "custom", path: ["reported", "asOf"], message: "the reported index is dated after the as-of date"});
209	  if (input.reported) {
210	    const text = input.reported.definition.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
211	    for (const component of input.reported.netDebtComponents) {
212	      const words = COMPONENT_WORDS[component];
213	      if (words && !words.test(text)) context.addIssue({code: "custom", path: ["reported", "definition"], message: `the reported definition text never names the component ${component} it claims to count; the literal definition and the structured components disagree`});
214	    }
215	    // The other direction: a component the text names must be in the structured list, with derivatives on the side the text gives them.
216	    const listed = new Set<string>(input.reported.netDebtComponents);
217	    for (const [component, words] of Object.entries(COMPONENT_WORDS)) {
218	      if (component === "derivative_liabilities" || component === "derivative_assets" || component === "other_onerous_debt") continue;
219	      if (words.test(text) && !listed.has(component)) context.addIssue({code: "custom", path: ["reported", "netDebtComponents"], message: `the reported definition text names ${component} and the structured components omit it; the literal definition and the structured components disagree`});
220	    }
221	    if (/derivativ/.test(text)) {
222	      const mentionsLiabilities = /derivativ[^.;]{0,40}passiv|passiv[^.;]{0,40}derivativ|derivative liabilit/.test(text);
223	      const mentionsAssets = /derivativ[^.;]{0,40}ativ(?!o? ?e)|ativ[^.;]{0,40}derivativ|derivative asset/.test(text);
224	      if (mentionsLiabilities && !listed.has("derivative_liabilities")) context.addIssue({code: "custom", path: ["reported", "netDebtComponents"], message: "the reported definition text adds derivative liabilities and the structured components omit them"});
225	      if (mentionsAssets && !listed.has("derivative_assets")) context.addIssue({code: "custom", path: ["reported", "netDebtComponents"], message: "the reported definition text deducts derivative assets and the structured components omit them"});
226	      if (!mentionsLiabilities && !mentionsAssets && (listed.has("derivative_liabilities") || listed.has("derivative_assets"))) context.addIssue({code: "custom", path: ["reported", "definition"], message: "the reported definition text mentions derivatives without their side (liabilities added, assets deducted); the polarity must be readable"});
227	    }
228	    if (/somente|apenas|only/.test(text) && input.reported.netDebtComponents.length > 2) context.addIssue({code: "custom", path: ["reported", "definition"], message: "the reported definition text restricts itself (somente/apenas/only) while the structured components list several; the literal definition and the structured components disagree"});
229	  }
230	});
231	export type CovenantReconciliationInput = z.input<typeof covenantReconciliationInputSchema>;
232	
233	type Comparability = "comparable" | "conditional" | "not_comparable" | "no_index";
234	type Calculation = {id: string; formula: string; operands: Record<string, string>; result: string; unit: string};
235	
236	export type CovenantReconciliationOutput = {
237	  schema_version: "method.reconcile-covenant-definitions.v13";
238	  as_of_date: string;
239	  /** The unit every value below is expressed in; part of the output and of its fingerprint. */
240	  unit: string;
241	  state: "resolved" | "conditioned" | "blocked";
242	  block_reasons: string[];
243	  covenants: Array<{
244	    instrument: string;
245	    source: "indenture" | "trustee_report";
246	    indexName: string;
247	    direction: "maximum" | "minimum" | null;
248	    definitions: {netDebt: string; netDebtComponents: string[]; ebitda: string; ebitdaAdjustments: Array<{id: string; kind: string; description: string; anchor: Anchor; obligation: {value: string; asOf: string; anchor: Anchor} | null}>; anchors: {netDebt: Anchor; ebitda: Anchor}} | null;
249	    measurement: {frequency: string; basis: string; fiscalYearEnd: string; nextMeasurementDate: string} | null;
250	    tiers: Array<{index: number; limit: string; condition: string; state: "applies" | "ended" | "not_yet" | "unproven" | "n/a"; anchor: Anchor}>;
251	    applicableLimit: string | null;
252	    limitState: "resolved" | "reported_by_trustee" | "insufficient_evidence";
253	    limitConditions: string[];
254	    reportedMeasurement: {value: string; asOf: string} | null;
255	    netDebtByDefinition: {value: string; formula: string; operands: Record<string, string>; anchors: Record<string, Anchor>; residualAssumedZero: boolean; numeratorObligations: string | null} | null;
256	    legalConditions: string[];
257	    index: {value: string; basis: "computed_from_components" | "reported"; ebitda: {value: string; basis: "opened" | "implied_from_reported"} | null; anchor: Anchor} | null;
258	    /** Facts that explain the tier resolution without being conditions: a proven acceleration, for instance. */
259	    notes: string[];
260	    comparability: Comparability;
261	    comparabilityReasons: string[];
262	    headroom: {absolute: string; relative: string | null; basis: string} | null;
263	    status: "within_limit" | "above_limit_interim" | "unresolved";
264	  }>;
265	  unproven_conditions: string[];
266	  /** Candidate lines and numerator obligations without a classified value, as insufficient_evidence, never added and never called absent. */
267	  uncovered_terms: Array<{id: string; state: "insufficient_evidence"; reason: string}>;
268	  legal_conditions: string[];
269	  trace: {calculations: Calculation[]; inputFingerprint: string; outputFingerprint: string};
270	};
271	
272	const d = (value: Decimal.Value) => new Decimal(value);
273	const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
274	const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
275	const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
276	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
277	const sortStrings = (values: readonly string[]) => [...values].sort(compare);
278	
279	const lastDay = (year: number, month: number) => new Date(Date.UTC(year, month, 0)).getUTCDate();
280	/** Next measurement after the as-of date: the fiscal year end and, for shorter frequencies, the month ends between. */
281	export function nextMeasurement(asOf: string, fiscalYearEnd: string, frequency: "annual" | "semiannual" | "quarterly"): string {
282	  const [endMonth, endDay] = fiscalYearEnd.split("-").map(Number) as [number, number];
283	  const step = frequency === "annual" ? 12 : frequency === "semiannual" ? 6 : 3;
284	  const year = Number(asOf.slice(0, 4));
285	  const candidates: string[] = [];
286	  for (const base of [year - 1, year, year + 1]) {
287	    for (let offset = 0; offset < 12; offset += step) {
288	      const total = endMonth - 1 + offset;
289	      const y = base + Math.floor(total / 12);
290	      const m = (total % 12) + 1;
291	      const day = endDay >= lastDay(2026, endMonth) ? lastDay(y, m) : Math.min(endDay, lastDay(y, m)); // a day at the month's end means the month's end, leap years included
292	      candidates.push(`${y}-${String(m).padStart(2, "0")}-${String(day).padStart(2, "0")}`);
293	    }
294	  }
295	  return candidates.filter((candidate) => candidate > asOf).sort(compare)[0]!;
296	}
297	
298	function canonical(input: z.infer<typeof covenantReconciliationInputSchema>) {
299	  return {
300	    ...input,
301	    candidateObligations: [...input.candidateObligations].sort((a, b) => compare(a.id, b.id)),
302	    instruments: [...input.instruments].sort((a, b) => compare(a.id, b.id)).map((instrument) => instrument.source === "indenture"
303	      ? {
304	          ...instrument,
305	          netDebtComponents: sortStrings(instrument.netDebtComponents) as NetDebtComponent[],
306	          ebitdaAdjustments: [...instrument.ebitdaAdjustments].sort((a, b) => compare(a.id, b.id)),
307	          tiers: instrument.tiers.map((tier) => tier.condition.type === "unconditional" ? tier : {...tier, condition: {...tier.condition, referenceInstruments: sortStrings(tier.condition.referenceInstruments)}}),
308	        }
309	      : instrument),
310	    referenceSettlements: [...input.referenceSettlements].sort((a, b) => compare(a.instrument, b.instrument)),
311	    componentValues: [...input.componentValues].sort((a, b) => compare(a.component, b.component)).map((line) => ({...line, covers: sortStrings(line.covers) as NetDebtComponent[]})),
