352	    // 1. Which tier applies, from dated facts only.
353	    const conditions: string[] = [];
354	    const notes: string[] = [];
355	    const tiers: CovenantReconciliationOutput["covenants"][number]["tiers"] = [];
356	    let applicable: {limit: string; tier: number} | null = null;
357	    instrument.tiers.forEach((tier, index) => {
358	      const condition = tier.condition;
359	      if (condition.type === "unconditional") {
360	        tiers.push({index, limit: tier.limit, condition: "unconditional", state: applicable ? "n/a" : "applies", anchor: tier.anchor});
361	        applicable ??= {limit: tier.limit, tier: index};
362	        return;
363	      }
364	      const facts = condition.referenceInstruments.map((reference) => settlements.get(reference) ?? null);
365	      // A reference instrument is over when it matured or was settled ordinarily on a proven date; an accelerated
366	      // settlement keeps the lower tier; a maturity passed without proof of settlement is unproven.
367	      const over = facts.map((fact) => {
368	        if (!fact) return "unknown" as const;
369	        const settledOn = fact.settlementDate !== null && fact.settlementDate <= input.asOfDate;
370	        if (fact.settlement === "ordinary" && settledOn) return "ordinary" as const;
371	        if (fact.settlement === "accelerated" && settledOn) return "accelerated" as const;
372	        if (fact.maturityDate <= input.asOfDate) return fact.settlement === "outstanding" ? "outstanding_after_maturity" as const : "matured_unproven" as const;
373	        return "alive" as const; // a settlement dated after the as-of date is not a fact yet
