378	        if (over.some((state) => state === "unknown")) {
379	          tiers.push({index, limit: tier.limit, condition: `until the first of ${label} matures or is settled ordinarily`, state: "unproven", anchor: tier.anchor});
380	          conditions.push(`the end of the ${tier.limit}x tier requires the maturity or settlement facts of every reference (${label}); the base lacks them for ${condition.referenceInstruments.filter((_reference, position) => over[position] === "unknown").join(", ")}${over.some((state) => state === "accelerated") ? "; an accelerated settlement of another reference does not settle the question" : ""}`);
