385	        }
386	        if (over.some((state) => state === "ordinary" || state === "matured_unproven" || state === "outstanding_after_maturity")) {
387	          tiers.push({index, limit: tier.limit, condition: `until the first of ${label} matures or is settled ordinarily`, state: "ended", anchor: tier.anchor});
388	          return;
389	        }
390	        tiers.push({index, limit: tier.limit, condition: `until the first of ${label} matures or is settled ordinarily`, state: "applies", anchor: tier.anchor});
391	        applicable ??= {limit: tier.limit, tier: index};
392	        return;
393	      }
394	      if (over.every((state) => state === "ordinary")) { tiers.push({index, limit: tier.limit, condition: `after ordinary settlement of ${label}`, state: "applies", anchor: tier.anchor}); applicable ??= {limit: tier.limit, tier: index}; return; }
395	      if (over.some((state) => state === "unknown")) { tiers.push({index, limit: tier.limit, condition: `after ordinary settlement of ${label}`, state: "unproven", anchor: tier.anchor}); conditions.push(`the ${tier.limit}x tier requires proof of ordinary settlement of every reference (${label}); the base lacks the facts of ${condition.referenceInstruments.filter((_reference, position) => over[position] === "unknown").join(", ")}`); return; }
396	      if (over.some((state) => state === "alive")) { tiers.push({index, limit: tier.limit, condition: `after ordinary settlement of ${label}`, state: "not_yet", anchor: tier.anchor}); return; }
397	      if (over.some((state) => state === "accelerated") && !over.some((state) => state === "outstanding_after_maturity" || state === "matured_unproven")) { tiers.push({index, limit: tier.limit, condition: `after ordinary settlement of ${label}`, state: "n/a", anchor: tier.anchor}); notes.push(`${label} was settled by acceleration on a proven date; the ${tier.limit}x tier does not apply (deterministic, no condition to prove)`); return; }
398	      tiers.push({index, limit: tier.limit, condition: `after ordinary settlement of ${label}`, state: "unproven", anchor: tier.anchor});
399	      if (over.some((state) => state === "outstanding_after_maturity")) conditions.push(`${label} matured and is recorded as outstanding; the ${tier.limit}x tier does not apply until ordinary settlement is proven`);
