 59	/** Deterministic permutation, different at every step. */
 60	const permute = <T>(items: readonly T[], seed: number): T[] => {
 61	  const copy = [...items];
 62	  let state = seed;
 63	  for (let index = copy.length - 1; index > 0; index -= 1) {
 64	    state = (state * 1103515245 + 12345) % 2147483648;
 65	    const swap = state % (index + 1);
 66	    [copy[index], copy[swap]] = [copy[swap]!, copy[index]!];
 67	  }
 68	  return copy;
 69	};
